import {diagnosticKey} from './issue-guidance.js';
import {esc,fmt} from './network-views.js';
import {wellGeometry,resolveEdge,crossSection} from './network-model.js';
export const isCalculationLimit=v=>v.code==='pit-overlap'||v.code==='trench-overlap'&&v.jointStatus==='failed';
export const isSoilCoverage=v=>v.code==='geometry'&&!v.message.startsWith('Исправьте параметры')&&v.message.includes('Грунтовые слои не покрывают дно');
export const issueKey=diagnosticKey;
export function uniqueIssues(issues){const direct=issues.filter(v=>v.code!=='network'&&!v.message.startsWith('Исправьте параметры')),seen=new Set();return issues.filter(v=>{if(v.code==='trench-overlap'&&v.jointStatus==='pending')return false;if((v.code==='network'||v.message.startsWith('Исправьте параметры'))&&direct.some(r=>v!==r&&v.message.includes(r.message)))return false;const key=issueKey(v);if(seen.has(key))return false;seen.add(key);return true}).map(v=>{if(!v.guidance?.key)return v;const related=[...new Set(issues.filter(o=>issueKey(o)===issueKey(v)).flatMap(o=>[o.objectId,...(o.related||[])]))].filter(id=>id!==v.objectId);return {...v,related}})}
const upDepth=value=>Math.ceil((value-1e-8)*100)/100;
export function soilRequirement(p,issue){if(!isSoilCoverage(issue))return null;const list=issue.kind==='well'?p.wells:p.edges,obj=list.find(v=>v.id===issue.objectId);if(!obj)return null;
 if(issue.kind==='well'){const depth=wellGeometry(obj,p).depth,covered=obj.layers.at(-1)?.bottom||0;return {object:obj,empty:!obj.layers.length,depth:upDepth(depth),covered,missing:Math.max(0,depth-covered)}}
 try{const res=resolveEdge(p,obj),last=obj.layers.at(-1);let max=0,worst=null;for(const section of obj.sections.filter(v=>v.method==='trench'))for(const station of [section.a*res.length,section.b*res.length,...res.points.filter(v=>v.s>section.a*res.length&&v.s<section.b*res.length).map(v=>v.s)]){const c=crossSection(obj,res,section,station),covered=last?last.start+(last.end-last.start)*station/res.length:0;max=Math.max(max,c.depth);if(!worst||c.depth-covered>worst.missing)worst={station,covered,missing:c.depth-covered,pointDepth:c.depth}}return {object:obj,empty:!obj.layers.length,depth:upDepth(max),...worst}}catch{return null}
}
export function soilTasksHTML(p,issues){const tasks=issues.map(v=>({issue:v,req:soilRequirement(p,v)})).filter(v=>v.req);if(!tasks.length)return '';return `<section class="soil-tasks"><b>Для расчёта укажите грунты · ${tasks.length}</b>${tasks.map(({issue,req})=>`<button data-action="issue" data-kind="${issue.kind}" data-id="${esc(issue.objectId)}" data-issue-tab="soils" data-issue-path="${issue.kind==='well'?'wells.'+p.wells.indexOf(req.object):'edges.'+p.edges.indexOf(req.object)}.layers" aria-label="Задать грунты ${esc(req.object.name)}"><span>${esc(req.object.name)}<small>${req.empty?'Не заданы':'Не хватает глубины'} · нужны до ${fmt(req.depth)} м</small></span><strong>Задать →</strong></button>`).join('')}</section>`}
export function issueText(p,issue){if(issue.guidance){const object=(issue.kind==='well'?p.wells:p.edges).find(v=>v.id===issue.objectId);return [issue.guidance.title,object?.name||'',issue.guidance.directions.join(' ')]}const req=soilRequirement(p,issue);if(req)return [req.empty?'Не заданы грунты':'Грунты описаны не на всю глубину',req.object.name,req.empty?'Укажите слои грунта до глубины '+fmt(req.depth)+' м.':'Дно достигает '+fmt(req.depth)+' м. В проблемной точке грунт описан до '+fmt(req.covered)+' м. Дополните слои.'];const e=p.edges.find(v=>v.id===issue.objectId),other=p.edges.find(v=>issue.related?.includes(v.id)),pair=[e?.name,other?.name].filter(Boolean).join(' и ');
 const map={
 'trench-overlap':['Не удалось рассчитать стык',pair,issue.message],
 'joint-soil-conflict':['Разные грунты в общей выемке',pair,'На отметке '+fmt(issue.location?.[2])+' м заданы разные грунты: '+(issue.soilIds||[]).map(id=>p.soils.find(s=>s.id===id)?.name||'не указан').join(' / ')+'. Согласуйте границы слоёв во вкладке «Грунты».'],
 'pit-overlap':['Нужен расчёт общего котлована','', 'Котлованы пересекаются. Это может быть верным проектным решением; программа пока не объединяет их объёмы.'],
 'pipe-clash':['Трубы пересекаются',pair,'Измените положение трубы или её высотные отметки.'],
 'pipe-self-clash':['Труба пересекает сама себя',e?.name,'Уберите лишний поворот в блоке «Повороты и профиль».'],
 'pipe-well-clash':['Труба проходит через чужой колодец',e?.name,'Переместите трубу или подключите её к этому колодцу.'],
 'rect-port-normal':['Труба входит в стену наискосок',e?.name,'Поверните колодец к трубе или выберите стену и поверните всю прямую трубу.'],
 'port-height':['Труба не помещается по высоте',e?.name,'Проверьте отметку низа трубы и высоту колодца.'],
 'port-width':['Труба шире стенки колодца',e?.name,'Проверьте диаметр трубы и внутренние размеры колодца.'],
 'geology-junction':['Грунты у трубы и колодца различаются',e?.name,'Проверьте слои во вкладке «Грунты».']};
 return map[issue.code]||[issue.message.replace(/^Исправьте параметры колодца «[^»]+»: /,''),'','Откройте параметры объекта и исправьте указанное значение.'];
}
export function limitDimensionsHTML(p,issue){if(issue.code!=='trench-overlap')return '';const ids=[issue.objectId,...(issue.related||[])];return '<div class="limit-dimensions">'+p.edges.filter(e=>ids.includes(e.id)).map(e=>{try{const res=resolveEdge(p,e),i=issue.sectionsByEdge?.[e.id]??0,s=e.sections[i],values=[s.a*res.length,s.b*res.length,...res.points.filter(v=>v.s>s.a*res.length&&v.s<s.b*res.length).map(v=>v.s)].map(station=>crossSection(e,res,s,station).top).filter(Number.isFinite),lo=Math.min(...values),hi=Math.max(...values);return `<small>${esc(e.name)} · зона ${i+1}: поверху ${fmt(lo)}${Math.abs(hi-lo)>.005?'–'+fmt(hi):''} м</small>`}catch{return ''}}).join('')+'</div>'}
export function issueButton(p,issue){const prefix=(issue.kind==='well'?'wells.'+p.wells.findIndex(v=>v.id===issue.objectId):'edges.'+p.edges.findIndex(v=>v.id===issue.objectId))+'.',focusPath=issue.paths?.find(v=>v.startsWith(prefix))||issue.paths?.[0]||'',object=(issue.kind==='well'?p.wells:p.edges).find(v=>v.id===issue.objectId),[title,context,help]=issueText(p,issue),g=issue.guidance;
 const repairs=g?.repairs?.map(r=>`<button data-action="repair-issue" data-kind="${r.kind}" data-id="${esc(r.id)}" data-repair-path="${esc(r.path)}" data-repair-tab="${r.tab}" data-repair-section="${r.section??g.section??''}" data-repair-station="${r.station??g.station??''}" data-repair-end="${r.end||''}">${esc(r.label)} →</button>`).join('');
 return `<article class="validation-issue ${isCalculationLimit(issue)?'limitation':issue.severity}"><b>${esc(title)}</b>${context?`<span>${esc(context)}</span>`:''}${g?.facts?.length?`<div class="issue-facts">${g.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div>`:''}<span>${esc(g?g.directions[0]:help)}</span>${limitDimensionsHTML(p,issue)}<div class="issue-actions"><button data-action="show-problem" data-issue-key="${esc(issueKey(issue))}">Показать на плане</button>${repairs|| (object?`<button data-action="issue" data-kind="${issue.kind}" data-id="${esc(issue.objectId)}" data-issue-code="${esc(issue.code)}" data-issue-section="${issue.sectionsByEdge?.[issue.objectId]??''}" data-issue-tab="${issue.tab||'geometry'}" data-issue-path="${esc(focusPath)}">${isSoilCoverage(issue)?'Задать грунты':isCalculationLimit(issue)?'Посмотреть размеры':'Открыть параметры'}</button>`:'')}</div>${g?.directions.length>1?`<details class="issue-alternatives"><summary>Другие варианты</summary><p>${esc(g.directions.slice(1).join(' '))}</p></details>`:''}</article>`;
}
export function diagnosticsHTML(p,issues){if(!p.wells.length)return '';const all=uniqueIssues(issues),errors=all.filter(v=>v.severity==='error'&&!isCalculationLimit(v)),limits=all.filter(isCalculationLimit),warnings=all.filter(v=>v.severity==='warning');if(!all.length)return '<div class="validation-ok">✓ Геометрия и связи проверены</div>';return `<details class="validation-summary"><summary>Проверка · исправить: ${errors.length} · ограничений расчёта: ${limits.length}${warnings.length?' · замечаний: '+warnings.length:''}</summary><div class="validation-scroll">${soilTasksHTML(p,errors)}${errors.filter(v=>!isSoilCoverage(v)).map(v=>issueButton(p,v)).join('')}${limits.length?'<h4>Ограничения программы · менять параметры не требуется</h4>'+limits.map(v=>issueButton(p,v)).join(''):''}${warnings.map(v=>issueButton(p,v)).join('')}</div></details>`}
export function markValidationFields(root,p,state,issues){
 for(const note of root.querySelectorAll('.field-issue'))note.remove();
 for(const node of root.querySelectorAll('[data-validation-paths]')){if(!node.dataset.invalidDraft)node.removeAttribute('aria-invalid');node.removeAttribute('title');delete node.dataset.validationPaths;node.classList.remove('field-warning')}
 const edge=p.edges.findIndex(v=>v.id===state.edgeId),well=p.wells.findIndex(v=>v.id===state.wellId);
 for(const node of root.querySelectorAll('[data-path],[data-command]')){
  let path=node.dataset.path;
  if(!path){const cmd=node.dataset.command;path=cmd==='diameter-mm'?`edges.${edge}.diameter`:cmd==='wall-mm'?`edges.${edge}.pipeWall`:['floor','well-working-height'].includes(cmd)?`wells.${well}.workingHeight`:cmd==='well-neck-height'?`wells.${well}.neckHeight`:cmd==='well-height'?`wells.${well}.height`:cmd==='boundary'?`edges.${edge}.sections.${node.dataset.index}.${node.dataset.part}`:cmd==='layer-thickness'?`${node.dataset.target}.${node.dataset.index}.${node.dataset.part}`:''}
  const relational=new Set(['trench-overlap','pit-overlap','pipe-clash','pipe-self-clash','pipe-well-clash','rect-port-normal','port-openings']);const found=issues.filter(v=>!isCalculationLimit(v)&&!isSoilCoverage(v)&&(!relational.has(v.code)||v.guidance?.badPaths?.length)&&!v.message.startsWith('Исправьте параметры колодца')&&(v.guidance?.badPaths||v.paths)?.some(k=>path===k||path.startsWith(k+'.')));node.dataset.validationPaths=path;
  if(found.length){const error=found.some(v=>v.severity==='error');if(error)node.setAttribute('aria-invalid','true');else node.classList.add('field-warning');node.title=[...new Set(found.map(v=>v.guidance?.directions.join(' ')||v.message))].join('\n');const label=node.closest?.('label');if(label){const note=label.ownerDocument.createElement('small');note.className='field-issue';note.textContent=found[0].guidance?.directions[0]||found[0].message;label.append(note)}}
  if(!found.length&&node.type==='number'&&!node.readOnly&&!node.dataset.optional){const cmd=node.dataset.command,value=node.value===''?NaN:Number(node.value),positive=['well-height','well-working-height','pipe-length'].includes(cmd),nonnegative=cmd==='well-neck-height';if(!Number.isFinite(value)||positive&&value<=0||nonnegative&&value<0){node.setAttribute('aria-invalid','true');const label=node.closest('label');if(label){const note=label.ownerDocument.createElement('small');note.className='field-issue';note.textContent=positive?'Введите число больше нуля.':nonnegative?'Введите ноль или положительное число.':'Введите числовое значение.';label.append(note)}}}

 }
}
